// src/components/CreateUrl.js
import React, { useEffect, useState } from 'react';
import { Box, TextField, Button, Container, Typography, FormGroup, Fade, CircularProgress, Tooltip, Card, CardMedia } from '@mui/material';
import { useNavigate, useParams } from 'react-router-dom';
import { toast, ToastContainer } from 'react-toastify';
import axios from "axios";
import { QRCodeSVG } from 'qrcode.react';
import { AdapterMoment } from '@mui/x-date-pickers/AdapterMoment';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { renderTimeViewClock } from '@mui/x-date-pickers/timeViewRenderers';
import { DELETE_UPDATE_URL_ROUTE, INSERT_URL_ROUTE, UPDATE_URL_ROUTE } from '../config/routeConfig';
import { getToken, isLoggedIn } from '../utils/GenUtils';
import AlertBox from './Alert/AlertBox';
import moment from 'moment';
import AlertSnackbar from './Alert/Snackbar';
import MediaPreview from './Alert/MediaPreview';

let errorObject = {
  main: false,
  originalUrl: false,
  urlName: false,
  expirationDate: false,
  OU_helperText: "",
  UN_helperText: "",
  ED_helperText: ""
}

function CreateUrl(props) {
  const [originalUrl, setOriginalUrl] = useState('');
  const [expirationDate, setExpirationDate] = useState(moment());
  const [urlName, setUrlName] = useState('');
  const [file, setFile] = useState({});
  const [error, setError] = useState(errorObject);
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [pageLoader, setPageLoader] = useState(false);
  const [snackbarOpen, setSnackbarOpen] = React.useState(false);
  const [snackbarMessage, setSnackbarMessage] = React.useState("");
  const [submit, setSubmit] = useState(false);
  const [fade, setFade] = useState(true);
  const navigate = useNavigate();
  const params = useParams();


  useEffect(() => {
    if (props.mode === 'update') {
      viewUrlDetails();
    }
  }, [props.mode])

  // Modal open and close functions
  const handleClickOpen = () => {
    if (props.mode === 'add') {
      if (originalUrl || urlName) {
        setOpen(true);
      } else {
        navigate("/");
      }
    } else {
      navigate("/");
    }
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleConfirm = () => {
    setFade(false); // Start the fade-out effect
    setOpen(false);
    setTimeout(() => {
      setOriginalUrl("");
      setUrlName("")
      setError(errorObject);
      navigate("/")
    }, 500)
  }

  // Change handler for the input fields
  const handleChange = (e, error = '', type) => {
    console.log("Event");
    console.log(e, error = '', type);
    if (type && type === 'expirationDate') {
      // let value = e;
      // value = value ? new Date(value).toISOString() : new Date().toISOString()
      setExpirationDate(moment(e));
      setError(prevState => {
        return { ...prevState, expirationDate: false, ED_helperText: "" }
      })
    } else if (e.target.name === 'originalUrl') {
      setOriginalUrl(e.target.value);
      setError(prevState => {
        return { ...prevState, originalUrl: false, OU_helperText: "" }
      })
    } else if (e.target.name === 'urlName') {
      setUrlName(e.target.value);
      setError(prevState => {
        return { ...prevState, urlName: false, UN_helperText: "" }
      })
    }
  }

  // Clear the contents of expirationDate field externally
  const clearClicked = (elem, e) => {
    console.log("ClearClicked");
    console.log(elem);
    console.log(e);
    setExpirationDate('1970-01-01T00:00:00.000Z')
  }

  const viewUrlDetails = () => {
    setPageLoader(true)
    if (!navigator.onLine) {
      setSnackbarMessage("Offline: Not connected")
      setSnackbarOpen(true)
      // toast("Offline: Not connected");
      setPageLoader(false)
      return;
    }

    if (!isLoggedIn()) {
      // toast("Invalid session, please login again.");
      setSnackbarMessage("Invalid session, please login again.")
      setSnackbarOpen(true)
      setPageLoader(false)
      return;
    }

    axios.get(`${DELETE_UPDATE_URL_ROUTE}/${params.urlId}`, {
      headers: {
        'Authorization': getToken()
      }
    })
    .then(res => {
      if (res.data && res.data.code === 200) {
        let urlData = res.data.data;
        console.log("urlData");
        console.log(urlData);
        if (urlData.file?.length) {
          setFile(urlData.file[0])
        }
        setUrlName(urlData.urlName);
        setOriginalUrl(urlData.originalUrl);
        setExpirationDate(moment(urlData.expirationDate));
        setPageLoader(false)
      }
    })
    .catch(err => {
      setPageLoader(false)
      // toast(err.message);
      let {
        response: { data },
      } = err;
      if (data.status === 401) {
        navigate("/login");
      }
      setSnackbarMessage(data.message)
      setSnackbarOpen(true)
    })
  }

  const handleSnackbarClose = () => {
    setSnackbarOpen(false);
  }

  // Submit the form once validated which will sends the request to the server for creation of Short URL
  const handleSubmit = (e) => {
    console.log("Clicked", e);
    e.preventDefault();
    setLoading(true)
    if (!originalUrl || !expirationDate || !urlName) {
      if (!originalUrl) {
        setError(prevState => {
          return { ...prevState, originalUrl: true, OU_helperText: "This is required field",
            // urlName: false, UN_helperText: "",
            // expirationDate: false, ED_helperText: ""
          }
        })
      }

      if (!expirationDate) {
        setError(prevState => {
          return { ...prevState, expirationDate: true, ED_helperText: "This is required field" }
        })
      }

      if (!urlName) {
        setError(prevState => {
          return { ...prevState, urlName: true, UN_helperText: "This is required field" }
        })
      }
      setLoading(false)
      // toast("All fields are required!");
      setSnackbarMessage("All fields are required!");
      setSnackbarOpen(true);
      return;
    }
    // setError(false);
    console.log("originalUrl, expirationDate, urlName");
    console.log(originalUrl, expirationDate, urlName);
    // let mode = "add";
    let reqObj = {};
    if (props.mode === "add") {
      reqObj = { originalUrl, urlName, expirationDate }
    } else {
      reqObj["urlId"] = params.urlId;
      if (urlName) reqObj["urlName"] = urlName;
      if (expirationDate) reqObj["expirationDate"] = expirationDate;
    }
    axios({
      url: props.mode === "add" ? INSERT_URL_ROUTE : UPDATE_URL_ROUTE,
      method: props.mode === "add" ? "post" : "patch",
      headers: {
        Authorization: getToken(),
      },
      data: reqObj,
    })
      .then((res) => {
        console.log("Response::");
        console.log(res.data);
        let { data } = res;
        setLoading(false)
        setSnackbarMessage(data.message);
        setSnackbarOpen(true);
        // callback(res);
        // toast(data.message, { autoClose: 1500 });
        // setModalOpen(false);
        // setUrlId("");
        setOriginalUrl("");
        setUrlName("");
        setExpirationDate(moment())
        setSubmit(prevState => !prevState.submit)
        sessionStorage.setItem("page", 0)
        navigate("/");
      })
      .catch((err) => {
        console.log("Error::addUrl");
        console.log(err);
        setLoading(false)
        let {
          response: { data },
        } = err;
        if (data.status === 401) {
          navigate("/login");
        }
        let message = data.error ? data.error[0].message : data.message;
        setSnackbarMessage(message);
        setSnackbarOpen(true);
        // toast(message, { autoClose: 2000 });
      });
  };

  return (
    <Fade in={fade} timeout={500}>
      <Container sx={{ marginTop: 4 }}>
      <AlertSnackbar
        snackbarOpen={snackbarOpen}
        snackbarMessage={snackbarMessage}
        handleSnackbarClose={handleSnackbarClose}
      />
      {
        pageLoader ? (
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              height: '100vh',  // Make the Box fill the viewport height
              width: '100vw',   // Make the Box fill the viewport width
              position: 'fixed',  // Keep the spinner fixed to the viewport center
              backgroundColor: 'rgba(0, 0, 0, 0.1)',  // Dark background with 50% transparency
              zIndex: 9999,
              top: 0,
              left: 0,
            }}
          >
            <CircularProgress />
          </Box>
        ) : (
          <React.Fragment>
            <Typography variant="h5">{props.mode === "add" ? "Create" : "Update"} Short URL</Typography>
            <FormGroup>
              {
                props.mode === "update" ? (
                  <Tooltip title="Unable to update original url. Please create a new one" arrow>
                    <TextField
                      label="Original URL"
                      fullWidth
                      margin="normal"
                      value={originalUrl}
                      name="originalUrl"
                      error={error.originalUrl}
                      helperText={error.OU_helperText}
                      type="url"
                      placeholder="Enter a valid url starting with http or https"
                      onChange={handleChange}
                      disabled={true}
                    />
                  </Tooltip>
                ) : (
                  <TextField
                    label="Original URL"
                    fullWidth
                    margin="normal"
                    value={originalUrl}
                    name="originalUrl"
                    error={error.originalUrl}
                    helperText={error.OU_helperText}
                    type="url"
                    placeholder="Enter a valid url starting with http or https"
                    onChange={handleChange}
                  />
                )
              }
              <TextField
                label="URL Name"
                fullWidth
                margin="normal"
                name="urlName"
                placeholder="Description of the URL"
                error={error.urlName}
                helperText={error.UN_helperText}
                value={urlName}
                onChange={handleChange}
              />
              <LocalizationProvider dateAdapter={AdapterMoment}>
                <DateTimePicker
                  label="Expiration Date"
                  name="expirationDate"
                  format="DD/MM/YYYY hh:mm a"
                  showDaysOutsideCurrentMonth={true}
                  value={expirationDate}
                  slotProps={{
                    textField: {
                      fullWidth: true,
                      margin: "normal",
                      error: error.expirationDate,
                      helperText: error.ED_helperText
                    },
                    // field: { clearable: true },
                    actionBar: {
                      actions: ["cancel"],
                    },
                  }}
                  onChange={(value, error) =>
                    handleChange(value, error, "expirationDate")
                  }
                  viewRenderers={{
                    hours: renderTimeViewClock,
                    minutes: renderTimeViewClock,
                    seconds: renderTimeViewClock,
                  }}
                />
              </LocalizationProvider>

              {
                Object.keys(file).length > 0 && <MediaPreview file={file} originalUrl={originalUrl} />
              }

              <Box sx={{ marginTop: 3, display: 'flex', justifyContent: 'flex-end', gap: 3 }}>
                <Button onClick={handleSubmit} variant='contained' color="primary" disabled={loading}>
                  {loading ? <CircularProgress size={24} /> : (
                    props.mode === "update" ? 'Update' : 'Create'
                  )}
                </Button>
                <Button onClick={handleClickOpen} variant='outlined' color="primary" disabled={loading}>
                  Cancel
                </Button>
              </Box>
            </FormGroup>
          </React.Fragment>
        )
      }
      <AlertBox
        open={open}
        handleClose={handleClose}
        handleConfirm={handleConfirm}
        modalContent="Are you sure you want to go back? Your changes will not be saved."
      />
      {/* <ToastContainer /> */}
    </Container>
    </Fade>
  );
}

export default CreateUrl;
