import React, { useContext, useEffect, useState } from 'react';
import { TextField, Button, CircularProgress, Box, Typography, useTheme } from '@mui/material';
import UrlApi from '../data/UrlApi';
import { useNavigate } from 'react-router-dom';
import { setToken } from '../utils/GenUtils';
import '../styles/login.css';
import { UrlContext } from './UrlContext';

const defaultData = { 
  emailId: '',
  password: '',
};

const Login = ({ setLogin }) => {
  const navigate = useNavigate();
  const urlConsumer = useContext(UrlContext);
  const [userData, setUserData] = useState(defaultData);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const theme = useTheme(); // Access the theme

  useEffect(() => {
    sessionStorage.setItem("page", 0);
    sessionStorage.setItem("limit", 5);
    setLogin(true);
  }, [setLogin]);

  const handleValues = (e) => {
    setUserData({
      ...userData,
      [e.target.name]: e.target.value,
    });
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    UrlApi.login(userData, (err, res) => {
      if (err) {
        setError(err.data.message);
        setLoading(false);
        return;
      }
      setLoading(false);
      urlConsumer.disableLoginError();
      setToken(res.data.accessToken);
      setLogin(false);
      navigate("/");
    });
  };

  return (
    <Box 
      sx={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'center', 
        justifyContent: 'center', 
        height: '100vh', 
        backgroundColor: theme.palette.background.default 
      }}
    >
      <Box 
        component="form" 
        sx={{ 
          p: 3, 
          backgroundColor: theme.palette.background.paper, 
          borderRadius: 2, 
          boxShadow: theme.shadows[3], 
          width: '100%', 
          maxWidth: 400 
        }} 
        onSubmit={handleLogin}
      >
        <Typography variant="h4" component="h2" sx={{ mb: 2, textAlign: 'center' }}>
          Login
        </Typography>
        
        <TextField
          fullWidth
          label="Email"
          id="emailId"
          name="emailId"
          value={userData.emailId}
          onChange={handleValues}
          autoComplete="off"
          margin="normal"
          variant="outlined"
        />

        <TextField
          fullWidth
          label="Password"
          type="password"
          id="password"
          name="password"
          value={userData.password}
          onChange={handleValues}
          autoComplete="off"
          margin="normal"
          variant="outlined"
        />

        <Box sx={{ mt: 2, textAlign: 'center' }}>
          <Button 
            variant="contained" 
            type="submit" 
            color="primary" 
            disabled={loading}
            fullWidth
          >
            {loading ? <CircularProgress size={24} /> : 'Login'}
          </Button>
        </Box>

        {error && (
          <Typography variant="body2" color="error" sx={{ mt: 2, textAlign: 'center' }}>
            {error}
          </Typography>
        )}
      </Box>
    </Box>
  );
};

export default Login;
