import React, { useContext } from "react";
import { Link, useNavigate } from "react-router-dom";
import moment from "moment";
import { useTheme } from "@mui/material/styles";
import {
  TableRow,
  IconButton,
  useMediaQuery,
  Tooltip,
  Snackbar,
  Slide,
  Chip,
} from "@mui/material";
import CloseIcon from '@mui/icons-material/Close';
import TableCell from "@mui/material/TableCell";
import { Edit, Delete } from '@mui/icons-material';
import { DELETE_UPDATE_URL_ROUTE, REDIRECT_URL_ROUTE } from "../config/routeConfig";
import { getToken, trimDescription } from "../utils/GenUtils";
import AlertBox from "./Alert/AlertBox";
import { UrlContext } from "./UrlContext";
import axios from "axios";
import AlertSnackbar from "./Alert/Snackbar";

function SlideTransition(props) {
  return <Slide {...props} direction="left" />;
}

const UrlData = (props) => {
  const theme = useTheme();
  const navigate = useNavigate();
  const urlConsumer = useContext(UrlContext);
  const [open, setOpen] = React.useState(false);
  const [snackbarOpen, setSnackbarOpen] = React.useState(false);
  const [snackbarMessage, setSnackbarMessage] = React.useState("");
  const [loading, setLoading] = React.useState(false);
  const isDarkMode = theme.palette.mode === 'dark';
  const isSmallScreen = useMediaQuery(theme.breakpoints.down("sm"));
  const { shortUrl, urlName, timesClicked, expirationDate, _id, isExpired, isFileUrl } = props.urlData;
  const url = `${REDIRECT_URL_ROUTE}/${shortUrl}`;
  const date = moment(expirationDate).format("MMMM Do YYYY, h:mm:ss a");

  const updateUrlHandler = () => {
    console.log("updateUrlHandler::Event");
    console.log(_id);
    navigate(`/url/${_id}`);
  };

  const trimmedUrlName = trimDescription(isSmallScreen, urlName);

  const index =
    parseInt(sessionStorage.getItem("page"), 10) *
      parseInt(sessionStorage.getItem("limit"), 10) +
    props.index;

  const handleDelete = () => {
    setOpen(true);
  }

  const handleSnackbarClose = () => {
    setSnackbarOpen(false);
  }

  const handleConfirm = () => {
    // urlConsumer.handleDeleteUrl(_id);
    // console.log("id", id);
    setLoading(true);
    axios.delete(`${DELETE_UPDATE_URL_ROUTE}/${_id}`, {
      headers: {
        Authorization: getToken(),
      },
    })
    .then((res) => {
      console.log("Response::handleDeleteUrl");
      console.log(res);
      let { data } = res;
      setLoading(false);
      setOpen(false);
      setSnackbarMessage(data.message);
      navigate(0);
      setSnackbarOpen(true);
      // callback(res);
      // toast(data.message, { autoClose: 2000 });
      // setUrlId("");
      // setSubmit(prevState => !prevState.submit)
    })
    .catch((err) => {
      console.log("Error::handleDeleteUrl");
      console.log(err);
      setLoading(false);
      // setOpen(false);
      let {
        response: { data },
      } = err;
      if (data.status === 401) {
        navigate("/login");
      }
      setSnackbarMessage(data.message);
      setSnackbarOpen(true);
    });
  };

  const handleClose = () => {
    setOpen(false);
  };

  return (
    <React.Fragment>
      <AlertBox
        loading={loading}
        open={open}
        handleClose={handleClose}
        handleConfirm={handleConfirm}
        modalContent="Are you sure, you want to delete this url ?"
      />
      <AlertSnackbar
        snackbarOpen={snackbarOpen}
        snackbarMessage={snackbarMessage}
        handleSnackbarClose={handleSnackbarClose}
     />
      <TableRow 
        key={_id}
        sx={{
          "&:hover": { backgroundColor: isExpired ? isDarkMode
            ? 'rgba(255, 99, 71, 0.1)' // Light red for dark mode
            : 'rgba(255, 99, 71, 0.3)' // Light red for light mode
          : 'action.hover' },
          backgroundColor: isExpired ? isDarkMode
                      ? 'rgba(255, 99, 71, 0.2)' // Light red for dark mode
                      : 'rgba(255, 99, 71, 0.4)' // Light red for light mode
                    : 'inherit'
        }}
      >
        <TableCell>
          <span>{index}</span>
        </TableCell>
        <TableCell>
          <Tooltip title={shortUrl} arrow>
            <span>
              <Link to={url} target="_blank">
                {shortUrl}
              </Link>
            </span>
          </Tooltip>
        </TableCell>
        <TableCell>
          <Tooltip title={urlName} arrow>
            {isFileUrl && (
              <Chip
                label="File"
                // variant="outlined"
                // color="primary" // You can change this to 'secondary', 'success', etc.
                size="small"
                sx={{ marginRight: 1 }}
              />
            )}
            <span>{trimmedUrlName}</span>
          </Tooltip>
        </TableCell>
        <TableCell>
          <span>{timesClicked}</span>
        </TableCell>
        <TableCell>
          <span>{date}</span>
        </TableCell>
        <TableCell sx={{ textAlign: 'center', display: 'flex', justifyContent: 'center', gap: 2 }}>
          <IconButton color="primary" onClick={updateUrlHandler}>
            <Edit />
          </IconButton>
          <IconButton color="secondary" onClick={handleDelete}>
            <Delete />
          </IconButton>
        </TableCell>
      </TableRow>
    </React.Fragment>
  );
};

export default UrlData;
