import React from "react";
import UrlApi from "../data/UrlApi";
import { getToken, isLoggedIn } from '../utils/GenUtils'
import { DELETE_UPDATE_URL_ROUTE } from "../config/routeConfig";
import axios from "axios";
export const UrlContext = React.createContext();

export class UrlProvider extends React.Component {

  constructor(props) {
    super(props);
    this.state = {
      list: [],
      // maxPage: 1,
      pageNum: 1,
      totalCount: 0,
      rowsPerPage: 5,
      error: false,
      loading: false,
      emptyList: false,
      deleteLoader: false,
      delete: false,
    }
  }

  handlePageChange = (e, page) => {
    console.log("handlePageChange::page", page);
    this.setState(() => ({
      pageNum: page
    }), () => {
      sessionStorage.setItem("page", page)
      sessionStorage.setItem("limit", this.state.rowsPerPage)
      this.loadUrlList(page)
    });
  };

  handleRowPerPageChange = (e) => {
    console.log("handleRowPerPageChange::", e.target.value);
    this.setState(() => ({
      rowsPerPage: parseInt(e.target.value, 10)
    }), () => {
      sessionStorage.setItem("page", 0)
      sessionStorage.setItem("limit", this.state.rowsPerPage)
      this.loadUrlList(0);
    });
  };

  loadUrlList = (page = 0) => {
    if (!navigator.onLine) {
      console.error("Offline: Not connected");
      this.setState(prevState => ({
        // snackbarOpen: !prevState.snackbarOpen,
        // snackbarMessage: "Network disconnected. You are offline",
        pageNum: 0,
        maxPage: 1,
        loading: false,
        error: true
      }))
      return;
    }
    if (!isLoggedIn()) {
      console.error("Invalid session, please login again.");
      this.setState(() => ({
        error: true
      }))
      return;
    }
    this.setState(() => ({ loading: true, pageNum: page }));
    let pageStorage = parseInt(sessionStorage.getItem("page"), 10);
    let limit = parseInt(sessionStorage.getItem("limit"), 10);
    console.log("pageStorage::", pageStorage);
    console.log("limit::", limit);
    let bodyData = {
      skip: pageStorage * limit,
      limit: limit,
      sortBy: "createdAt",
      sortOrder: -1
    }
    UrlApi.listUrl(bodyData, (result) => {
      console.log("UrlApi.listUrl::res.data");
      console.log(result.data);
      if (result?.data?.code === 200) {
        // this.context.initUrlList(res);
        let { total, data: { listing }} = result.data;
        if (listing.length > 0) {
          this.setState(() => ({
            loading: false,
            list: listing,
            totalCount: total
          }))
        } else {
          this.setState(() => ({
            emptyList: true
          }))
        }
      } else {
        this.setState(() => ({
          error: true
        }))
        console.error("Some error occured", result);
      }
    })
  }

  componentDidUpdate(prevProps, prevState) {
    console.log("PrevProps", prevProps);
    console.log("PrevState", prevState);
    if (prevState.delete !== this.state.delete) {
      this.props.navigation.navigate('/');
    }
  }

  handleDeleteUrl = (id) => {
    console.log("id", id);
    this.setState(() => ({ deleteLoader: true }));
    setTimeout(() => {
      axios.delete(`${DELETE_UPDATE_URL_ROUTE}/${id}`, {
        headers: {
          Authorization: getToken(),
        },
      })
      .then((res) => {
        console.log("Response::handleDeleteUrl");
        console.log(res);
        this.setState((prevState) => ({ deleteLoader: false, delete: !prevState.delete }));
        // callback(res);
        let { data } = res;
        // toast(data.message, { autoClose: 2000 });
        // setModalOpen(false);
        // setUrlId("");
        // setSubmit(prevState => !prevState.submit)
      })
      .catch((err) => {
        console.log("Error::handleDeleteUrl");
        console.log(err);
        this.setState(() => ({ deleteLoader: false }));
        let {
          response: { data },
        } = err;
        // toast(data.message, { autoClose: 2000 });
      });
    }, 5000)
  }

  disableLoginError = () => {
    this.setState((prevState) => ({
      error: false
    }))
  }

  addUrl = (item) => {
    this.setState((prevState) => ({
      list: [...prevState.list, item]
    }))
  }

  render() {
    return (
      <UrlContext.Provider value={{
        ...this.state,
        initUrlList: () => this.loadUrlList(),
        handlePageChange: (e, page) => this.handlePageChange(e, page),
        handleRowPerPageChange: (e) => this.handleRowPerPageChange(e),
        addItem: (item) => this.addUrl(item),
        handleDeleteUrl: (id) => this.handleDeleteUrl(id),
        disableLoginError: () => this.disableLoginError(),
      }}>
        {this.props.children}
      </UrlContext.Provider>  
    )
  }

}

export const UrlConsumer = UrlContext.Consumer;
