import React from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Button,
  MenuItem,
  Box,
} from "@mui/material";
import { List, Info, Logout } from "@mui/icons-material";
import { useTheme } from "@mui/material/styles";
import { LightMode, DarkMode } from "@mui/icons-material";
import { NavLink, useNavigate } from "react-router-dom";
import UrlApi from "../data/UrlApi";
import { removeToken } from "../utils/GenUtils";

const Navbar = ({ darkMode, toggleDarkMode, login }) => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isDarkMode = theme.palette.mode === "dark";
  const logoutBtnStyle = {
    visibility: !login ? "visible" : "hidden",
  };
  const [loading, setLoading] = React.useState(false);
  const handleLogout = (e) => {
    e.preventDefault();
    setLoading(true);
    UrlApi.logout((err, result) => {
      if (err) {
        console.error("Error occured", err);
        return;
      }
      // setDisplay('none');
      setLoading(false);
      removeToken();
      navigate("/login");
    });
  };
  return (
    <AppBar position="sticky" sx={{ top: 0 }}>
      <Toolbar sx={{ justifyContent: "space-between" }}>
        {/* Left side: List and About */}
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <NavLink
            to="/"
            style={({ isActive }) => ({
              textDecoration: "none",
              color: isActive ? (isDarkMode ? "#fff" : "#000") : "inherit", // White for dark mode, black for light mode
              display: "flex",
              alignItems: "center",
              padding: "8px 16px",
              borderRadius: "8px",
              backgroundColor: isActive
                ? isDarkMode
                  ? "#424242"
                  : "#e0f7fa"
                : "transparent", // Grey for dark mode, light blue for light mode
              transition: "background-color 0.3s ease",
            })}
          >
            <MenuItem>
              <List sx={{ mr: 1 }} />
              <Typography variant="body1">List</Typography>
            </MenuItem>
          </NavLink>

          <NavLink
            to="/about"
            style={({ isActive }) => ({
              textDecoration: "none",
              color: isActive ? (isDarkMode ? "#fff" : "#000") : "inherit", // White for dark mode, black for light mode
              display: "flex",
              alignItems: "center",
              padding: "8px 16px",
              borderRadius: "8px",
              backgroundColor: isActive
                ? isDarkMode
                  ? "#424242"
                  : "#e0f7fa"
                : "transparent", // Grey for dark mode, light blue for light mode
              transition: "background-color 0.3s ease",
            })}
          >
            <MenuItem>
              <Info sx={{ mr: 1 }} />
              <Typography variant="body1">About</Typography>
            </MenuItem>
          </NavLink>
        </Box>

        {/* Center: App Title */}
        <Typography variant="h6" component="div">
          Short URL Manager
        </Typography>

        {/* Right side: Dark mode switch and Logout button */}
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          {/* Dark Mode Switch */}
          <Box sx={{ display: "flex", alignItems: "center" }}>
            {/* <Typography variant="body2" sx={{ mr: 1 }}>
                        {darkMode ? "Dark Mode" : "Light Mode"}
                    </Typography> */}
            <IconButton onClick={toggleDarkMode} color="inherit">
              {darkMode ? <DarkMode /> : <LightMode />}
            </IconButton>
          </Box>

          {/* Logout Button */}
          <Button
            style={logoutBtnStyle}
            color="inherit"
            onClick={handleLogout}
            disabled={loading}
            startIcon={<Logout />}
          >
            Logout
          </Button>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
